const powTex = (b, x) => `${Array.isArray(b) ? `\\left(\\dfrac{${b[0]}}{${b[1]}}\\right)` : b}^{${ratTex(xr(x))}}`;
/** b^x = N, verified */
const expTex = (b, x, N, Ntex) => { must(powEq(b, x, N), `power ${b}^${x} = ${N}`); return `${powTex(b, x)} = ${Ntex ?? nTex(N)}`; };
/** log_b N = x, verified */
const logTex = (b, N, x, Ntex) => { must(rEq(logExact(b, N), xr(x)), `log_${b} ${N} = ${x}`); return `\\log_{${bTex(b)}} ${Ntex ?? nTex(N)} = ${ratTex(xr(x))}`; };
const numExp = (cs, es) => [[2.3, 5.1, 1.7, 3.9], [11, 0.4, 3.2, 2.6], [7.5, 9.1, 0.2, 1.3]].every((p) => Math.abs(cs.reduce((s, c, i) => s + c * Math.log10(p[i]), 0) - Math.log10(es.reduce((m, e, i) => m * p[i] ** e, 1))) < 1e-12);

