const formRows = [[2, 5, 32], [10, 3, 1000], [5, -2, [1, 25]], [9, [1, 2], 3], [16, [3, 4], 8], [[1, 2], 4, [1, 16]]];
const formsTable = table(['Exponential form', 'Logarithmic form'], formRows.map(([b, x, N]) => [d(expTex(b, x, N)), d(logTex(b, N, x))]), 'Table with six facts, each written as a power and as a logarithm. Two to the five is thirty two, so log base two of thirty two is five. Ten cubed is one thousand. Five to the minus two is one twenty fifth. Nine to the half is three. Sixteen to the three quarters is eight. One half to the fourth is one sixteenth.', 'The base stays the base, the exponent becomes the logarithm, and the result of the power becomes the number.');
