const partsTable = table(['Symbol', 'Name', 'Condition'], [[d('a'), 'base', d('a > 0, \\ a \\ne 1')], [d('N'), 'number (the argument)', d('N > 0')], [d('x'), 'the logarithm', 'any real number'], [d(logTex(2, 8, 3)), 'base $2$, number $8$, logarithm $3$', d(expTex(2, 3, 8))]], 'Table naming the parts of log base a of N equals x. The base a must be positive and not one. The number N must be positive. The logarithm x can be any real number. Example: log base two of eight equals three, with base two, number eight and logarithm three, because two cubed is eight.', 'In $\\log_{a} N = x$ the base is $a$, the number is $N$ and the logarithm is $x$.');
const e1Rows = [[3, 4, 81], [7, -1, [1, 7]], [8, [2, 3], 4], [10, -3, [1, 1000], '0.001']];
must(1 / 1000 === 0.001, 'ex1 decimal');
const ex1Table = table(['Exponential form', 'Base, exponent, number', 'Logarithmic form'], e1Rows.map(([b, x, N, Nt]) => [d(expTex(b, x, N, Nt)), d(`${b}, \\ ${ratTex(xr(x))}, \\ ${Nt ?? nTex(N)}`), d(logTex(b, N, x, Nt))]), 'Table with four statements changed from exponential to logarithmic form. Three to the fourth is eighty one. Seven to the minus one is one seventh. Eight to the two thirds is four. Ten to the minus three is zero point zero zero one. Each shows base, exponent, number and the logarithmic form.', 'Identify the base, the exponent and the number, then write $\\log_{a} N = x$.');
must(powEq(8, [5, 3], 32) && rEq(logExact(8, 32), rat(5, 3)) && powEq(2, 5, 32) && 3 * 5 / 3 === 5, 'ex2');
const ex2Table = table(['Step', 'Working'], [['Name it', d('x = \\log_{8} 32')], ['Exponential form', d('8^{x} = 32')], ['Same base', d('\\left(2^{3}\\right)^{x} = 2^{5}, \\ \\text{so} \\ 2^{3x} = 2^{5}')], ['Equate exponents', d('3x = 5, \\ \\text{so} \\ x = \\dfrac{5}{3}')], ['Check', d(expTex(8, [5, 3], 32))]], 'Table of five steps finding log base eight of thirty two. Call it x, write eight to the x equals thirty two, rewrite both sides as powers of two so that two to the three x equals two to the five, equate exponents to get x equals five thirds, and check that eight to the five thirds is thirty two.', 'Write both sides as powers of one base, then compare exponents.');
must([-3, 0, 2, 7].every((x) => 1 ** x === 1) && Number.isNaN((-2) ** 0.5) && [-3, -1, 0, 2, 5].every((x) => 2 ** x > 0), 'restrictions');
const whyTable = table(['If the...', 'What goes wrong', 'So we require'], [['base is $1$', d('1^{x} = 1 \\text{ for every } x'), d('a \\ne 1')], ['base is negative, say $-2$', d('(-2)^{\\frac{1}{2}} \\text{ is not a real number}'), d('a > 0')], ['number is $0$ or negative', d('2^{x} > 0 \\text{ for every real } x'), d('N > 0')]], 'Table of three restrictions. A base of one is useless because one to any power is one. A negative base such as minus two has no real value for minus two to the half. A number that is zero or negative can never equal a positive base raised to a power.', 'A logarithm needs $a > 0$, $a \\ne 1$ and $N > 0$.');
const spBases = [2, 5, 10, 13, [1, 2]];
