const shiftTable = table(['Number', 'Working', d('\\log')], shiftRows, 'Table of five numbers built from seven. Given log seven is zero point eight four five one, log seventy is one point eight four five one, log seven hundred is two point eight four five one, log zero point seven is minus zero point one five four nine and log zero point zero seven is minus one point one five four nine.', 'Moving the decimal point changes $\\log$ by a whole number, because $\\log 10 = 1$.');
const ex3Table = table(['Step', 'Working'], [['Exponential form', d(`x^{-4} = ${nTex([1, 81])}`)], ['Take reciprocals', d('x^{4} = 81')], ['Fourth root, positive base', d('x = 3')], ['Check', d(expTex(3, -4, [1, 81]))]], 'Table of four steps to find the base x when log base x of one eighty first is minus four. Write x to the minus four equals one eighty first, so x to the fourth is eighty one, so x is three, because a base is positive. Check that three to the minus four is one eighty first.', 'A base is always positive, so reject $x = -3$.');
must(powEq(3, 4, 81) && !powEq(-3 + 0, 3, 81) && powEq([3, 1], -4, [1, 81]), 'ex3');
must(powEq(4, [5, 2], 32) && 4 ** 2.5 === 32, 'ex4');
const ex4Table = table(['Step', 'Working'], [['Exponential form', d('x = 4^{\\frac{5}{2}}')], ['Square root first', d('4^{\\frac{1}{2}} = 2')], ['Then the power', d('x = 2^{5} = 32')], ['Check', d(logTex(4, 32, [5, 2]))]], 'Table of four steps to find x when log base four of x is five halves. Then x is four to the five halves. The square root of four is two, so x is two to the fifth, which is thirty two. Check that log base four of thirty two is five halves.', 'Take the root named by the denominator, then the power named by the numerator.');
const ex5 = (() => { const sc = dsub('4', '0.6990'); must(sc === '3.301' && law([[1, 5], [-4, 10]], [5, 10000]) && 5 / 10000 === 5e-4, 'ex5'); return sc; })();
const ex5Table = table(['Step', 'Working'], [['Concentration', d('c = 5 \\times 10^{-4}')], ['Take logarithms', d('\\log c = \\log 5 - 4')], ['Use the given value', d('\\log c = 0.6990 - 4 = -3.301')], ['Score', d(`-\\log c = ${ex5}`)]], 'Table of four steps for an acidity score defined as minus log c, with c equal to five times ten to the minus four and log five equal to zero point six nine nine zero. Log c is log five minus four, which is minus three point three zero one, so the score is three point three zero one.', 'The score $-\\log c$ is positive for small concentrations.');
const flow1 = flow('LR', [['a', '$a^{x} = N$'], ['b', '$\\log_{a} N = x$']], [['a', 'b', 'write as a logarithm'], ['b', 'a', 'write as a power']], 'Flow with two boxes: a to the x equals N, and log base a of N equals x. An arrow labelled write as a logarithm goes from the first to the second, and an arrow labelled write as a power goes back.', 'Two ways of saying the same fact.');
const sum1 = table(['Idea', 'Rule'], [['Two forms', d('a^{x} = N \\iff \\log_{a} N = x')], ['Conditions', d('a > 0, \\ a \\ne 1, \\ N > 0')], ['Special values', d('\\log_{a} 1 = 0, \\ \\log_{a} a = 1')], ['Common logarithm', d('\\log N \\text{ means } \\log_{10} N')], ['Finding an unknown', 'convert to exponential form, then match bases']], 'Summary table of part one. Powers and logarithms are two forms of one fact. The base is positive and not one and the number is positive. Log of one is zero and log of the base is one. A common logarithm has base ten. Convert to exponential form to find unknowns.', 'Part 1 at a glance.');

