// ---------------------------------------------------------------- deck 2 visuals
const g4 = (p) => (GV[p] / 10000).toFixed(4);
const prodRows = [[2, 3, 6], [3, 7, 21], [2, 5, 10], [5, 7, 35]].map(([m, n, mn]) => {
  must(m * n === mn && law([[1, m], [1, n]], mn), `product ${m} ${n}`);
  const s = fromGiven([[1, m], [1, n]]);
  must(Math.abs(Number(s) - lg(mn)) < 1e-3, 'product value near');
  return [d(String(m)), d(String(n)), d(`\\log ${m} + \\log ${n} = ${g4(m)} + ${g4(n)} = ${s}`), d(`\\log ${mn}`)];
});
must(fromGiven([[1, 2], [1, 5]]) === '1' && fromGiven([[1, 3], [1, 7]]) === '1.3222' && fromGiven([[1, 5], [1, 7]]) === '1.5441' && fromGiven([[1, 2], [1, 3]]) === '0.7781', 'product sums');
const prodTable = table(['$m$', '$n$', 'Sum of the logarithms (given values)', 'Same as'], prodRows, 'Table of four products using given values of logarithms. Log two plus log three is zero point seven seven eight one, the logarithm of six. Log three plus log seven is one point three two two two, the logarithm of twenty one. Log two plus log five is exactly one, the logarithm of ten. Log five plus log seven is one point five four four one, the logarithm of thirty five.', 'Adding logarithms corresponds to multiplying numbers: $\\log m + \\log n = \\log mn$.');
const proofFlow = flow('TB', [['a', 'Let $\\log_{a} m = x$ and $\\log_{a} n = y$'], ['b', 'So $m = a^{x}$ and $n = a^{y}$'], ['c', 'Then $mn = a^{x} \\times a^{y} = a^{x + y}$'], ['d', 'So $\\log_{a}(mn) = x + y$'], ['e', '$\\log_{a}(mn) = \\log_{a} m + \\log_{a} n$']], [['a', 'b'], ['b', 'c'], ['c', 'd'], ['d', 'e']], 'Flow chart proving the product law: let the logs of m and n be x and y; then m is a to the x and n is a to the y; their product is a to the x plus y; so the log of m n is x plus y; so the log of the product is the sum of the logs.', 'The product law is the law of indices $a^{x} a^{y} = a^{x + y}$ read backwards.');
must([[2, 3], [5, 7]].every(([x, y]) => Math.abs(Math.log(x * y) / Math.log(4) - (Math.log(x) / Math.log(4) + Math.log(y) / Math.log(4))) < 1e-12), 'product law in base 4');
const quoRows = [['$\\log 1000 - \\log 10$', 'log', [[1, 1000], [-1, 10]], 100, 10], ['$\\log_{2} 96 - \\log_{2} 3$', 'log', [[1, 96], [-1, 3]], 32, 2], ['$\\log_{3} 54 - \\log_{3} 2$', 'log', [[1, 54], [-1, 2]], 27, 3], ['$\\log 7 - \\log 70$', 'log', [[1, 7], [-1, 70]], [1, 10], 10]].map(([diff, , terms, t, base]) => { must(law(terms, t, base), `quotient ${diff}`); const v = logExact(base, t); const b = base === 10 ? '' : `_{${base}}`; return [diff, d(`\\log${b} ${nTex(t)}`), d(ratTex(v))]; });
const quoTable = table(['Difference', 'Single logarithm', 'Value'], quoRows, 'Table of four differences. Log one thousand minus log ten is log one hundred, which is two. Log base two of ninety six minus log base two of three is log base two of thirty two, which is five. Log base three of fifty four minus log base three of two is log base three of twenty seven, which is three. Log seven minus log seventy is log of one tenth, which is minus one.', 'Subtracting logarithms corresponds to dividing numbers: $\\log \\dfrac{m}{n} = \\log m - \\log n$.');
const powRows = (() => {
  must(law([[5, 2]], 32) && dmul('5', '0.3010') === '1.505' && law([[-3, 2]], [1, 8]) && dmul('-3', '0.3010') === '-0.903', 'power rows');
  must(Math.abs(Math.log10(Math.sqrt(10)) - 0.5) < 1e-15 && logExact(5, 5 ** 7).n === 7, 'power rows 2');
  return [['$\\log 32$', '$5\\log 2$', '$5 \\times 0.3010 = 1.505$'], ['$\\log \\dfrac{1}{8}$', '$-3\\log 2$', '$-3 \\times 0.3010 = -0.903$'], ['$\\log \\sqrt{10}$', '$\\dfrac{1}{2}\\log 10$', '$\\dfrac{1}{2}$'], ['$\\log_{5} 5^{7}$', '$7\\log_{5} 5$', '$7$']];
})();
const powTable = table(['Expression', 'Power law', 'Value'], powRows, 'Table of four power-law examples. Log thirty two is five log two, which is one point five zero five. Log of one eighth is minus three log two, which is minus zero point nine zero three. Log of the square root of ten is one half of log ten, which is one half. Log base five of five to the seven is seven times log base five of five, which is seven.', 'The power becomes a multiplier: $\\log m^{p} = p\\log m$, and so $\\log_{a} a^{x} = x$.');
const ex1Comb = (() => { must(law([[1, 8], [1, 125]], 1000) && 8 * 125 === 1000 && logExact(10, 1000).n === 3, 'comb'); return table(['Step', 'Working'], [['Product law', d('\\log 8 + \\log 125 = \\log (8 \\times 125)')], ['Multiply', d('= \\log 1000')], ['Powers of ten', d('= 3')]], 'Table of three steps simplifying log eight plus log one hundred twenty five. The product law gives log of eight times one hundred twenty five, which is log one thousand, which equals three.', 'Spot a product that makes a power of $10$.'); })();
const ex2Comb = (() => { must(law([[2, 5], [3, 2]], 200) && 25 * 8 === 200 && vEq(vcomb([[2, 5], [3, 2]]), 200), 'comb2'); return table(['Step', 'Working'], [['Power law first', d('2\\log 5 + 3\\log 2 = \\log 5^{2} + \\log 2^{3}')], ['Evaluate the powers', d('= \\log 25 + \\log 8')], ['Product law', d('= \\log 200')]], 'Table of three steps writing two log five plus three log two as one logarithm. Use the power law to get log twenty five plus log eight, then the product law to get log two hundred.', 'Power law first, then product or quotient law.');})();
const expRows = [['$\\log (ab)$', '$\\log a + \\log b$', [1, 1, 0, 0], [1, 1, 0, 0]], ['$\\log \\dfrac{a}{b}$', '$\\log a - \\log b$', [1, -1, 0, 0], [1, -1, 0, 0]], ['$\\log \\dfrac{x^{3} y^{2}}{z}$', '$3\\log x + 2\\log y - \\log z$', [3, 2, -1, 0], [3, 2, -1, 0]], ['$\\log \\sqrt{\\dfrac{x}{y}}$', '$\\dfrac{1}{2}\\log x - \\dfrac{1}{2}\\log y$', [0.5, -0.5, 0, 0], [0.5, -0.5, 0, 0]], ['$\\log \\dfrac{1}{x^{4}}$', '$-4\\log x$', [-4, 0, 0, 0], [-4, 0, 0, 0]]].map(([a, b, cs, es]) => { must(numExp(cs, es), `expansion ${a}`); return [a, b]; });
const expTable = table(['Expression', 'Expanded'], expRows, 'Table of five expressions and their expansions. Log of a b is log a plus log b. Log of a over b is log a minus log b. Log of x cubed y squared over z is three log x plus two log y minus log z. Log of the square root of x over y is half log x minus half log y. Log of one over x to the fourth is minus four log x.', 'Product and quotient laws split the expression; the power law brings the powers down.');
const ex3Exp = (() => { must(numExp([3, 0.5, -2, -1], [3, 0.5, -2, -1]) && !numExp([3, 0.5, -2, 1], [3, 0.5, -2, -1]), 'exp3'); return table(['Step', 'Working'], [['Split top and bottom', d('\\log \\dfrac{a^{3}\\sqrt{b}}{c^{2} d} = \\log (a^{3}\\sqrt{b}) - \\log (c^{2} d)')], ['Product law on each part', d('= \\log a^{3} + \\log b^{\\frac{1}{2}} - \\left(\\log c^{2} + \\log d\\right)')], ['Power law, remove the bracket', d('= 3\\log a + \\dfrac{1}{2}\\log b - 2\\log c - \\log d')]], 'Table of three steps expanding log of a cubed root b over c squared d. Split into log of the top minus log of the bottom, use the product law on each, then the power law, and remove the bracket carefully so that both log c squared and log d are subtracted.', 'The minus sign in front of the bracket applies to both terms inside.'); })();
const inTerms = [['$12$', [[2, 2], [1, 3]], 12, '$2\\log 2 + \\log 3$'], ['$15$', [[1, 3], [1, 5]], 15, '$\\log 3 + \\log 5$'], ['$18$', [[1, 2], [2, 3]], 18, '$\\log 2 + 2\\log 3$'], ['$5$', [[1, 10], [-1, 2]], 5, '$1 - \\log 2$'], ['$0.3$', [[1, 3], [-1, 10]], [3, 10], '$\\log 3 - 1$']].map(([n, terms, target, shown]) => { must(law(terms, target), `in terms of ${n}`); let v; if (n === '$5$') v = dsub('1', '0.3010'); else if (n === '$0.3$') v = dsub('0.4771', '1'); else v = fromGiven(terms); return [n, shown, d(v)]; });
must(inTerms.map((x) => x[2]).join() === '$1.0791$,$1.1761$,$1.2552$,$0.699$,$-0.5229$' && Math.abs(0.699 - lg(5)) < 1e-4, 'in terms values');
const inTable = table(['$N$', '$\\log N$ in terms of $\\log 2$, $\\log 3$, $\\log 5$', 'Value (given logs)'], inTerms, 'Table of five numbers written using the logarithms of two, three and five, with log ten equal to one. Twelve is two log two plus log three, one point zero seven nine one. Fifteen is log three plus log five, one point one seven six one. Eighteen is log two plus two log three, one point two five five two. Five is one minus log two, zero point six nine nine. Zero point three is log three minus one, minus zero point five two two nine.', 'Factorise into $2$, $3$, $5$ (and $10$); the laws do the rest.');
const ex4Given = (() => { const v = fromGiven([[1, 2], [3, 3]]); must(v === '1.7323' && vEq(vcomb([[1, 2], [3, 3]]), 54) && 2 * 27 === 54, 'ex4'); return table(['Step', 'Working'], [['Factorise', d('54 = 2 \\times 27 = 2 \\times 3^{3}')], ['Laws', d('\\log 54 = \\log 2 + 3\\log 3')], ['Substitute', d('= 0.3010 + 3(0.4771) = 0.3010 + 1.4313')], ['Add', d(`= ${v}`)]], 'Table of four steps finding log fifty four from the given log two equal to zero point three zero one zero and log three equal to zero point four seven seven one. Fifty four is two times three cubed, so log fifty four is log two plus three log three, which is zero point three zero one zero plus one point four three one three, one point seven three two three.', 'Always factorise into the primes whose logarithms are given.'); })();
const ex5Eq = (() => { const ok = (x) => x > 0 && x - 2 > 0 && x * (x - 2) === 8; must(ok(4) && !ok(-2) && (-2) * (-4) === 8 && 4 * 4 - 2 * 4 - 8 === 0 && LT2(2, 4) === 2 && LT2(2, 2) === 1, 'ex5 equation'); return table(['Step', 'Working'], [['Product law', d('\\log_{2}\\,x(x - 2) = 3')], ['Exponential form', d('x(x - 2) = 2^{3} = 8')], ['Quadratic', d('x^{2} - 2x - 8 = 0, \\ \\text{so} \\ (x - 4)(x + 2) = 0')], ['Domain: $x > 0$ and $x - 2 > 0$', d('x = -2 \\text{ is rejected}, \\ x = 4')], ['Check', d('\\log_{2} 4 + \\log_{2} 2 = 2 + 1 = 3')]], 'Table of five steps solving log base two of x plus log base two of x minus two equals three. The product law gives x times x minus two equals eight, so x squared minus two x minus eight is zero, so x is four or minus two. Both logarithms need x greater than two, so reject minus two and keep four. Check: two plus one is three.', 'Always test each root against the domain.'); })();
function LT2(b, a) { const e = logExact(b, a); return e.d === 1 ? e.n : NaN; }
const ex6Eq = (() => { const ok = (x) => 3 * x - 5 > 0 && 3 * x - 5 === 16; must(ok(7) && powEq(4, 2, 16), 'ex6'); return table(['Step', 'Working'], [['Exponential form', d('3x - 5 = 4^{2} = 16')], ['Solve', d('3x = 21, \\ \\text{so} \\ x = 7')], ['Domain', d('3(7) - 5 = 16 > 0')]], 'Table of three steps solving log base four of three x minus five equals two. Write three x minus five equals sixteen, so x is seven. Check the domain: three times seven minus five is sixteen, which is positive.', 'Convert at once when there is a single logarithm.'); })();
const ex7Id = (() => { must(law([[1, 48], [-1, 3]], 16) && vEq(vcomb([[1, 48], [-1, 3]]), vcomb([[4, 2]])) && 48 / 3 === 16, 'ex7'); return table(['Step', 'Working'], [['Quotient law', d('\\log 48 - \\log 3 = \\log \\dfrac{48}{3}')], ['Divide', d('= \\log 16')], ['Power law, $16 = 2^{4}$', d('= \\log 2^{4} = 4\\log 2')]], 'Table of three steps proving log forty eight minus log three equals four log two. By the quotient law the left side is log of forty eight over three, which is log sixteen, and since sixteen is two to the fourth, this equals four log two.', 'Start from the more complicated side and work towards the other.'); })();
const lawsFlow = flow('TB', [['t', 'Laws of logarithms (same valid base)'], ['p', 'Product: $\\log_{a}(mn) = \\log_{a} m + \\log_{a} n$'], ['q', 'Quotient: $\\log_{a}\\dfrac{m}{n} = \\log_{a} m - \\log_{a} n$'], ['w', 'Power: $\\log_{a} m^{p} = p\\log_{a} m$']], [['t', 'p'], ['t', 'q'], ['t', 'w']], 'Flow with a heading, the laws of logarithms, and three boxes below it: the product law, the quotient law and the power law, each written in symbols.', 'Three laws, one base.');
const sum2 = table(['Idea', 'Rule'], [['Product', d('\\log (mn) = \\log m + \\log n')], ['Quotient', d('\\log \\dfrac{m}{n} = \\log m - \\log n')], ['Power', d('\\log m^{p} = p\\log m, \\ \\log_{a} a^{x} = x')], ['Equations', 'combine, convert, solve, then check the domain'], ['Not allowed', d('\\log (m + n) \\ne \\log m + \\log n')]], 'Summary table of part two: the product, quotient and power laws; solving equations by combining, converting, solving and checking the domain; and a warning that the log of a sum is not the sum of the logs.', 'Part 2 at a glance.');

// ---------------------------------------------------------------- deck 2
const d2 = deck({
  part: 2,
  title: 'Logarithms — Part 2: The laws, expanding and simplifying, and equations',
  goals: ['State and use the product, quotient and power laws', 'Expand an expression into logarithms of its factors and combine logarithms into one', 'Write logarithms in terms of log 2, log 3 and log 5 and use given values', 'Solve simple logarithm equations with a domain check and prove simple identities'],
  slides: [
    sl('title', 'Logarithms, Part 2', { b: 'Three laws turn **products into sums**, **quotients into differences** and **powers into multipliers**.', v: lawsFlow, n: 'Welcome to part two. Logarithms are useful because of three laws. A logarithm turns a product into a sum, a quotient into a difference, and a power into a multiplier. In this part we prove and use these laws, expand and combine expressions, use given values, solve equations and prove identities.' }),
    sl('concept', 'What you will be able to do', { ul: ['State and use the **product, quotient and power laws**', '**Expand** and **combine** logarithmic expressions', 'Write logarithms using $\\log 2$, $\\log 3$, $\\log 5$ and **given values**', 'Solve **logarithm equations**, checking the domain', 'Prove simple **identities**'], n: 'These are your goals for part two. We learn the three laws and why they hold. We expand an expression into separate logarithms and combine separate logarithms into one. We use given values, solve equations while checking the domain, and prove simple identities.' }),
    sl('concept', 'The product law', { b: '$\\log_{a}(mn) = \\log_{a} m + \\log_{a} n$ for positive $m$ and $n$. The base must be the same on both sides.', v: prodTable, n: 'The product law says the logarithm of a product is the sum of the logarithms. Look at the table. The logarithm of two plus the logarithm of three gives the logarithm of six. The logarithm of two plus the logarithm of five is exactly one, which is the logarithm of ten. The sum is easier to handle than the product, which is why logarithms were invented.' }),
    sl('concept', 'Why the product law holds', { b: 'It is the law of indices $a^{x} \\times a^{y} = a^{x+y}$ written in logarithmic form.', v: proofFlow, n: 'Here is the proof. Let the logarithm of m be x and the logarithm of n be y. Then m is a to the x and n is a to the y. Multiplying, m n is a to the x plus y, because we add indices when we multiply powers. Writing that as a logarithm, the logarithm of m n is x plus y, which is the sum of the two logarithms.' }),
    sl('concept', 'The quotient law', { b: '$\\log_{a}\\dfrac{m}{n} = \\log_{a} m - \\log_{a} n$. It comes from $\\dfrac{a^{x}}{a^{y}} = a^{x-y}$.', v: quoTable, n: 'The quotient law says the logarithm of a quotient is the difference of the logarithms. The logarithm of a thousand minus the logarithm of ten is the logarithm of a hundred, which is two. It works in any base, as the second and third rows show. And the logarithm of seven minus the logarithm of seventy is the logarithm of one tenth, which is minus one.' }),
    sl('check', 'Quick check: recognising the product law', { b: 'Which line is correct for every positive $m$ and $n$?', chk: 'm09', n: 'Test each line with small numbers such as two and three. Only one of the lines is true every time.' }),
    sl('concept', 'The power law', { b: '$\\log_{a} m^{p} = p\\log_{a} m$. In particular $\\log_{a} a^{x} = x$.', v: powTable, n: 'The power law says the logarithm of a power is the exponent times the logarithm. So the logarithm of thirty two is five times the logarithm of two. A fraction like one eighth is two to the minus three, giving minus three times the logarithm of two. A square root is a power of one half. And the logarithm of five to the seven, to base five, is simply seven.' }),
    sl('example', 'Worked example 1: combining with the product law', { b: 'Simplify $\\log 8 + \\log 125$.', ul: ['**Step 1 —** Product law: $\\log (8 \\times 125)$.', '**Step 2 —** $8 \\times 125 = 1000$.', '**Answer —** $\\log 1000 = 3$.'], v: ex1Comb, n: 'Add the two logarithms by multiplying the numbers. Eight times one hundred twenty five is one thousand, a power of ten. The logarithm of one thousand is three. Whenever you add logarithms, look for factors that multiply to a power of the base, such as ten, one hundred or one thousand.' }),
    sl('example', 'Worked example 2: power law then product law', { b: 'Write $2\\log 5 + 3\\log 2$ as a single logarithm.', ul: ['**Step 1 —** Power law: $\\log 5^{2} + \\log 2^{3}$.', '**Step 2 —** $\\log 25 + \\log 8$.', '**Answer —** $\\log 200$.'], v: ex2Comb, n: 'When there are multipliers in front of the logarithms, use the power law first. Two log five becomes the logarithm of twenty five, and three log two becomes the logarithm of eight. Then the product law gives the logarithm of twenty five times eight, which is two hundred. Always move the multipliers inside before combining.' }),
    sl('check', 'Quick check: a cancelling pair', { b: 'Move each multiplier inside its logarithm first.', chk: 'm14', n: 'Use the power law to write each term as a single logarithm. Compare the two numbers you get, and decide what their difference is.' }),
    sl('concept', 'Expanding an expression', { b: 'To **expand**, split products and quotients, then bring powers down. A root is a power: $\\sqrt{x} = x^{\\frac{1}{2}}$.', v: expTable, n: 'Expanding means writing one logarithm as a sum of simple logarithms. Split products into sums, quotients into differences, and bring the powers down. A square root counts as a power of one half. A reciprocal, such as one over x to the fourth, gives a minus sign and so the logarithm is minus four log x.' }),
    sl('example', 'Worked example 3: expanding with four letters', { b: 'Expand $\\log \\dfrac{a^{3}\\sqrt{b}}{c^{2} d}$.', ul: ['**Step 1 —** $\\log (a^{3}\\sqrt{b}) - \\log (c^{2} d)$.', '**Step 2 —** $\\log a^{3} + \\log b^{\\frac{1}{2}} - (\\log c^{2} + \\log d)$.', '**Answer —** $3\\log a + \\dfrac{1}{2}\\log b - 2\\log c - \\log d$.'], v: ex3Exp, n: 'First split the top from the bottom with the quotient law. Then split each product with the product law. The bottom is inside a bracket after a minus sign. Finally the power law brings down the three, the half and the two. When the bracket is removed, both the log of c squared and the log of d are subtracted.' }),
    sl('check', 'Quick check: spot the right expansion', { b: 'Apply the three laws one at a time.', chk: 'm16', n: 'Split the fraction first, then the product on top, then bring down the powers. Be careful with the sign of the term from the bottom.' }),
    sl('concept', 'In terms of log 2, log 3, log 5', { b: 'Factorise the number into $2$, $3$, $5$. Use $\\log 10 = 1$: for example $\\log 5 = \\log \\dfrac{10}{2} = 1 - \\log 2$.', v: inTable, n: 'A very common task is to write a logarithm using only the logarithms of two, three and five. Factorise the number. Twelve is two squared times three. Eighteen is two times three squared. And five is ten divided by two, so its logarithm is one minus the logarithm of two. Zero point three is three tenths, so we subtract one.' }),
    sl('example', 'Worked example 4: using given values', { b: 'Given $\\log 2 = 0.3010$ and $\\log 3 = 0.4771$, find $\\log 54$.', ul: ['**Step 1 —** $54 = 2 \\times 3^{3}$.', '**Step 2 —** $\\log 54 = \\log 2 + 3\\log 3$.', '**Answer —** $0.3010 + 1.4313 = 1.7323$.'], v: ex4Given, n: 'When values are given, factorise into the numbers whose logarithms you know. Fifty four is two times twenty seven, and twenty seven is three cubed. So the logarithm is the logarithm of two plus three times the logarithm of three. Three times zero point four seven seven one is one point four three one three, and adding zero point three zero one zero gives one point seven three two three.' }),
    sl('example', 'Worked example 5: a logarithm equation', { b: 'Solve $\\log_{2} x + \\log_{2}(x - 2) = 3$.', ul: ['**Step 1 —** $\\log_{2}\\,x(x - 2) = 3$, so $x(x - 2) = 8$.', '**Step 2 —** $(x - 4)(x + 2) = 0$.', '**Domain —** $x > 2$, so reject $x = -2$. **Answer —** $x = 4$.'], v: ex5Eq, n: 'Combine the two logarithms with the product law, then convert to a power. The product x times x minus two equals two cubed, which is eight. That is a quadratic with roots four and minus two. But both logarithms need x to be greater than two, so minus two is rejected. The only solution is four, and the check gives two plus one equals three.' }),
    sl('example', 'Worked example 6: a single logarithm', { b: 'Solve $\\log_{4}(3x - 5) = 2$.', ul: ['**Step 1 —** $3x - 5 = 4^{2} = 16$.', '**Step 2 —** $x = 7$.', '**Domain —** $3(7) - 5 = 16 > 0$.'], v: ex6Eq, n: 'With a single logarithm, convert at once. Three x minus five equals four squared, which is sixteen. So three x is twenty one and x is seven. Always finish with the domain check: when x is seven, the argument is sixteen, which is positive, so the solution is valid.' }),
    sl('example', 'Worked example 7: proving an identity', { b: 'Show that $\\log 48 - \\log 3 = 4\\log 2$.', ul: ['**Step 1 —** Quotient law: $\\log \\dfrac{48}{3} = \\log 16$.', '**Step 2 —** $16 = 2^{4}$.', '**Conclusion —** $\\log 2^{4} = 4\\log 2$.'], v: ex7Id, n: 'To prove an identity, start from the more complicated side. The quotient law turns the difference into the logarithm of forty eight over three, which is sixteen. Sixteen is two to the fourth, so the power law gives four times the logarithm of two. That is exactly the right side, so the identity is proved.' }),
    sl('check', 'Quick check: a quotient equation', { b: 'Combine, convert, solve, then check the domain.', chk: 'n6', n: 'Use the quotient law to make one logarithm, convert to a power, and solve the resulting equation. Finally test that every argument is positive.' }),
    sl('summary', 'Summary', { ul: ['Product: $\\log mn = \\log m + \\log n$', 'Quotient: $\\log \\dfrac{m}{n} = \\log m - \\log n$', 'Power: $\\log m^{p} = p\\log m$', 'Equations: combine, convert, solve, **check the domain**', '$\\log (m + n)$ is **not** $\\log m + \\log n$'], v: sum2, n: 'To sum up part two. The product law adds, the quotient law subtracts, and the power law multiplies. To solve an equation, combine the logarithms, convert to a power, solve, and always check the domain. And remember: the logarithm of a sum is not the sum of the logarithms.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Expand or combine (2 marks):** law used 1 + result 1', '**Given values (3 marks):** factorise 1 + laws 1 + arithmetic 1', '**Equation (3 marks):** combine and convert 1 + solve 1 + domain check 1', '**Mistake:** $\\log (m + n) = \\log m + \\log n$', '**Mistake:** $\\dfrac{\\log m}{\\log n} = \\log m - \\log n$', '**Mistake:** keeping a root that makes an argument negative, or losing the minus sign on a term from a bracket'], n: 'In expansion questions, name the law you are using. For given values, show the factorisation first. In equations, you must check the domain, because a root that makes an argument negative has to be rejected. Never write that the logarithm of a sum is the sum of the logarithms, and never turn a quotient of logarithms into a difference.' }),
  ],
});

// ---------------------------------------------------------------- notes
const kt = (term, definition_md) => ({ term, definition_md });
const notes = {
  unit: 'icse-9-mathematics-ch07', version: 1, title: 'Logarithms — chapter notes', language: 'en',
  sections: [
    { heading: '1. Exponential form and logarithmic form', body_md: r`A **logarithm** is an exponent. The two statements $a^{x} = N$ and $\log_{a} N = x$ say the same thing, with $a > 0$, $a \ne 1$ and $N > 0$.

- In $\log_{a} N = x$: $a$ is the **base**, $N$ the **number** (argument) and $x$ the **logarithm**.
- To convert, keep the base, turn the exponent into the logarithm, and put the result of the power after the base: $8^{\frac{2}{3}} = 4 \iff \log_{8} 4 = \dfrac{2}{3}$.
- To evaluate $\log_{8} 32$, put $x = \log_{8} 32$, write $8^{x} = 32$, rewrite both sides as powers of $2$, and equate the exponents: $2^{3x} = 2^{5}$, so $x = \dfrac{5}{3}$.`, key_terms: [kt('Logarithm', 'The exponent to which the base must be raised to give the number: $\\log_{a} N = x$ means $a^{x} = N$.'), kt('Base', 'The positive number $a \\ne 1$ in $\\log_{a} N$.'), kt('Argument', 'The number $N > 0$ whose logarithm is taken.')], formulas: [{ latex: r`a^{x} = N \iff \log_{a} N = x`, label: 'The two forms' }], visual: formsTable, visuals: [ex1Table, ex2Table, flow1], topic_ids: [topic(1)] },
    { heading: '2. Valid bases and numbers; two special values', body_md: r`A base must be positive and not $1$: if $a = 1$ every power is $1$, and a negative base has no real value for a power such as $\frac{1}{2}$. A number must be positive, because a positive base raised to any power is positive: $\log_{5} 0$ and $\log_{5}(-25)$ do not exist. A logarithm itself can be negative or a fraction.

- $\log_{a} 1 = 0$ because $a^{0} = 1$.
- $\log_{a} a = 1$ because $a^{1} = a$; more generally $\log_{a} a^{x} = x$.
- The graph of $y = \log x$ crosses the $x$-axis at $x = 1$ and lies to the right of the $y$-axis.`, key_terms: [kt('Domain of a logarithm', 'Only positive numbers have logarithms: $N > 0$.')], formulas: [{ latex: r`\log_{a} 1 = 0, \quad \log_{a} a = 1`, label: 'Special values' }, { latex: r`\log_{a} a^{x} = x`, label: 'Logarithm of a power of the base' }], visual: whyTable, visuals: [specialTable, plot2, logPlot], topic_ids: [topic(1)] },
    { heading: '3. Common logarithms and given values', body_md: r`When no base is written the base is $10$: $\log N$ means $\log_{10} N$. A power of ten has a whole-number logarithm: $\log 0.001 = -3$, $\log 1000 = 3$. Because $\log 10 = 1$, moving the decimal point changes the logarithm by a whole number: if $\log 7 = 0.8451$ then $\log 70 = 1.8451$ and $\log 0.07 = -1.1549$.

In problems the needed values (for example $\log 2 = 0.3010$, $\log 3 = 0.4771$) are **given**; log tables and antilog tables are not required.

**Number of digits:** if $\log N = k + f$ with $k$ a whole number and $0 \le f < 1$, then $N$ has $k + 1$ digits. For $2^{40}$: $40 \times 0.3010 = 12.04$, so $13$ digits.`, key_terms: [kt('Common logarithm', 'A logarithm to base $10$, written $\\log N$.')], formulas: [{ latex: r`\log 10^{n} = n`, label: 'Powers of ten' }], visual: commonTable, visuals: [shiftTable, ex5Table], topic_ids: [topic(1), topic(3)] },
    { heading: '4. The product and quotient laws', body_md: r`For positive $m$ and $n$ and a valid base $a$:

- **Product law:** $\log_{a}(mn) = \log_{a} m + \log_{a} n$.
- **Quotient law:** $\log_{a}\dfrac{m}{n} = \log_{a} m - \log_{a} n$.

They are the laws of indices $a^{x} a^{y} = a^{x+y}$ and $\dfrac{a^{x}}{a^{y}} = a^{x-y}$ in logarithmic form. Both sides must use the **same base**. A logarithm of a sum or difference does not split: $\log (m + n) \ne \log m + \log n$, and $\dfrac{\log m}{\log n} \ne \log m - \log n$.

Examples: $\log 5 + \log 2000 = \log 10000 = 4$; $\log_{2} 40 - \log_{2} 5 = \log_{2} 8 = 3$.`, key_terms: [kt('Product law', 'The logarithm of a product is the sum of the logarithms.'), kt('Quotient law', 'The logarithm of a quotient is the difference of the logarithms.')], formulas: [{ latex: r`\log_{a}(mn) = \log_{a} m + \log_{a} n`, label: 'Product law' }, { latex: r`\log_{a}\dfrac{m}{n} = \log_{a} m - \log_{a} n`, label: 'Quotient law' }], visual: prodTable, visuals: [proofFlow, quoTable], topic_ids: [topic(2)] },
    { heading: '5. The power law', body_md: r`**Power law:** $\log_{a} m^{p} = p\log_{a} m$, from $(a^{x})^{p} = a^{px}$. It works for fractions and roots too: $\log \dfrac{1}{8} = -3\log 2$ and $\log \sqrt{10} = \dfrac{1}{2}\log 10 = \dfrac{1}{2}$. In particular $\log_{a} a^{x} = x$.

When a logarithm has a multiplier in front, use the power law first to move it inside: $2\log 5 + 3\log 2 = \log 25 + \log 8 = \log 200$. Check: $4\log 3 - 2\log 9 = \log 81 - \log 81 = \log 1 = 0$.`, key_terms: [kt('Power law', 'The logarithm of a power is the exponent times the logarithm of the base of the power.')], formulas: [{ latex: r`\log_{a} m^{p} = p\log_{a} m`, label: 'Power law' }], visual: powTable, visuals: [ex1Comb, ex2Comb, lawsFlow], topic_ids: [topic(2)] },
    { heading: '6. Expanding and combining; in terms of log 2, log 3, log 5', body_md: r`**Expanding:** split products and quotients, then bring the powers down. $\log \dfrac{x^{3} y^{2}}{z} = 3\log x + 2\log y - \log z$. A minus sign in front of a bracket changes every term inside it: $-(\log c^{2} + \log d) = -2\log c - \log d$.

**Combining:** the reverse; powers first, then products and quotients: $2\log 3 + \dfrac{1}{2}\log 16 - \log 6 = \log \dfrac{9 \times 4}{6} = \log 6$.

**In terms of $\log 2$, $\log 3$, $\log 5$:** factorise into $2$, $3$, $5$ and use $\log 10 = 1$, so $\log 5 = 1 - \log 2$: $\log 12 = 2\log 2 + \log 3$ and $\log 0.3 = \log 3 - 1$. With given values: $\log 54 = \log 2 + 3\log 3 = 0.3010 + 1.4313 = 1.7323$.`, key_terms: [kt('Expand', 'Write one logarithm as a sum and difference of simpler logarithms.')], formulas: [{ latex: r`\log 5 = 1 - \log 2`, label: 'From $\\log 2 + \\log 5 = \\log 10 = 1$' }], visual: expTable, visuals: [ex3Exp, inTable, ex4Given], topic_ids: [topic(3)] },
    { heading: '7. Equations and identities', body_md: r`**Equations.** Combine the logarithms with the laws into one logarithm on each side, convert to exponential form (or equate the arguments), solve, and then **check the domain**: every argument must be positive. A root that makes an argument zero or negative is rejected.

- $\log_{4}(3x - 5) = 2 \Rightarrow 3x - 5 = 16 \Rightarrow x = 7$.
- $\log_{2} x + \log_{2}(x - 2) = 3 \Rightarrow x(x - 2) = 8 \Rightarrow x = 4$ or $-2$; the domain $x > 2$ rejects $-2$.

**Identities.** Start from the more complicated side and use the laws until you reach the other side: $\log 48 - \log 3 = \log 16 = 4\log 2$. If $\log (x + y) = \log x + \log y$ then $x + y = xy$.`, key_terms: [kt('Extraneous root', 'A solution of the algebra that makes an argument non-positive, and so is not a solution of the logarithm equation.')], formulas: [{ latex: r`\log_{a} u = \log_{a} v \Rightarrow u = v \quad (u, v > 0)`, label: 'Equal logarithms' }], visual: ex5Eq, visuals: [ex6Eq, ex7Id, sum2], topic_ids: [topic(3)] },
  ],
  exam_tips_md: r`**How marks are awarded**
- *Conversion between forms (1 mark each):* base, exponent and number in the right places.
- *Evaluate or find an unknown base or number (2 marks):* exponential form 1; result 1 (reject a negative base).
- *Expand or combine (2 marks):* law named and used 1; result 1.
- *Given values (3 marks):* factorise into the given primes 1; laws 1; arithmetic 1.
- *Equation (3 marks):* combine and convert 1; solve 1; domain check 1.
- *10-mark structured question:* parts (a), (b), (c), usually 3 + 3 + 4; show all working.

**Common mistakes**
1. Swapping $N$ and $x$ when changing form, or forgetting that the base must be positive.
2. Believing $\log_{a} 1 = 1$ or $\log_{a} a = 0$ (it is the other way round).
3. Writing $\log (m + n) = \log m + \log n$, or $\dfrac{\log m}{\log n} = \log m - \log n$.
4. Forgetting that a minus sign in front of a bracket changes every term inside it.
5. Mixing bases in one law.
6. Keeping a root that makes an argument negative; always check the domain.`,
  status: 'draft', provenance: d1.provenance,
};

// ---------------------------------------------------------------- flashcards
const fc = (id, front_md, back_md, tag, t) => ({ id, front_md, back_md, tag, topic_id: topic(t) });
must(rEq(logExact(2, 32), rat(5)) && rEq(logExact(10, [1, 1000]), rat(-3)) && rEq(logExact(8, 4), rat(2, 3)), 'cards');
must(law([[1, 6], [1, 35], [-1, 21]], 10) && law([[1, 5], [1, 20]], 100) && law([[1, 3], [1, 7]], 21) && law([[3, 2]], 8) && law([[1, 10], [-1, 2]], 5) && law([[2, 2], [1, 3]], 12) && law([[1, 3], [-1, 10]], [3, 10]), 'cards laws');
must(fromGiven([[1, 2], [1, 3]]) === '0.7781' && dsub('1', '0.3010') === '0.699' && digitsOf(2, 40) === 13 && dmul('40', '0.3010') === '12.04', 'cards numbers');
must(powEq(5, 3, 125) && powEq(3, -2, [1, 9]) && logExact(10, 10 ** 6).n === 6 && numExp([2, -3, 0, 0], [2, -3, 0, 0]), 'cards powers');
const flashcards = {
  unit: 'icse-9-mathematics-ch07', version: 1, language: 'en',
  cards: [
    fc('f01', 'What is a **logarithm**?', r`The exponent to which the base must be raised to give the number: $\log_{a} N = x$ means $a^{x} = N$.`, 'definition', 1),
    fc('f02', 'What are the **base** and the **argument** in $\\log_{a} N$?', r`The base is $a$ ($a > 0$, $a \ne 1$); the argument is the number $N$ ($N > 0$).`, 'definition', 1),
    fc('f03', 'What is a **common logarithm**?', r`A logarithm to base $10$; $\log N$ means $\log_{10} N$.`, 'definition', 1),
    fc('f04', 'What does **expanding** a logarithm mean?', 'Writing one logarithm as a sum and difference of simpler logarithms using the three laws.', 'definition', 3),
    fc('f05', 'What is an **extraneous root** in a logarithm equation?', 'A root of the algebra that makes an argument zero or negative, so it must be rejected.', 'definition', 3),
    fc('f06', 'Exponential form of $\\log_{a} N = x$?', r`$a^{x} = N$.`, 'formula', 1),
    fc('f07', 'Product law?', r`$\log_{a}(mn) = \log_{a} m + \log_{a} n$ for $m, n > 0$.`, 'formula', 2),
    fc('f08', 'Quotient law?', r`$\log_{a}\dfrac{m}{n} = \log_{a} m - \log_{a} n$ for $m, n > 0$.`, 'formula', 2),
    fc('f09', 'Power law?', r`$\log_{a} m^{p} = p\log_{a} m$ for $m > 0$.`, 'formula', 2),
    fc('f10', 'What are $\\log_{a} 1$ and $\\log_{a} a$?', r`$\log_{a} 1 = 0$ and $\log_{a} a = 1$, for every valid base $a$.`, 'formula', 1),
    fc('f11', 'What is $\\log_{a} a^{x}$?', r`$x$: the logarithm undoes the power.`, 'formula', 2),
    fc('f12', 'Why can the number in a logarithm not be $0$ or negative?', r`A positive base raised to any real power is positive, so $a^{x}$ is never $0$ or negative.`, 'concept', 1),
    fc('f13', 'Why can the base not be $1$?', r`Because $1^{x} = 1$ for every $x$: $\log_{1} 8$ would have no value and $\log_{1} 1$ would have every value.`, 'concept', 1),
    fc('f14', 'Can a logarithm be negative?', r`Yes: $\log 0.001 = -3$ and $\log_{2}\dfrac{1}{64} = -6$. Only the number $N$ must be positive.`, 'concept', 1),
    fc('f15', 'How do you find an unknown base, as in $\\log_{x} \\dfrac{1}{81} = -4$?', r`Convert: $x^{-4} = \dfrac{1}{81}$, so $x^{4} = 81$ and $x = 3$ (the base is positive).`, 'concept', 1),
    fc('f16', 'Which law applies first to $2\\log 5 + 3\\log 2$?', r`The power law, giving $\log 25 + \log 8$; then the product law gives $\log 200$.`, 'concept', 3),
    fc('f17', 'What must you do after solving a logarithm equation?', 'Check the domain: every argument must be positive; reject any root that makes one non-positive.', 'concept', 3),
    fc('f18', 'What is $\\log 1000$?', r`$3$, because $1000 = 10^{3}$.`, 'fact', 1),
    fc('f19', 'What is $\\log 0.01$?', r`$-2$, because $0.01 = 10^{-2}$.`, 'fact', 1),
    fc('f20', 'Is $\\log (m + n) = \\log m + \\log n$?', r`No. The product law is for $\log (mn)$. For example $\log 2 \ne \log 1 + \log 1 = 0$.`, 'fact', 2),
    fc('f21', 'How many digits does $N$ have if $\\log N = 12.04$?', r`$13$: the whole-number part $12$ plus $1$.`, 'fact', 3),
    fc('f22', 'Write $8^{\\frac{2}{3}} = 4$ as a logarithm.', r`$\log_{8} 4 = \dfrac{2}{3}$.`, 'example', 1),
    fc('f23', 'Simplify $\\log 6 + \\log 35 - \\log 21$.', r`$\log \dfrac{6 \times 35}{21} = \log 10 = 1$.`, 'example', 2),
    fc('f24', 'Write $\\log 12$ using $\\log 2$ and $\\log 3$.', r`$12 = 2^{2} \times 3$, so $\log 12 = 2\log 2 + \log 3$.`, 'example', 3),
    fc('f25', 'Write $\\log 5$ using $\\log 2$ only.', r`$\log 5 = \log \dfrac{10}{2} = 1 - \log 2$.`, 'example', 3),
    fc('f26', 'First step when you are given $\\log 2$ and $\\log 3$ and asked for $\\log 54$?', r`Factorise: $54 = 2 \times 3^{3}$; then $\log 54 = \log 2 + 3\log 3$.`, 'exam-tip', 3),
    fc('f27', 'Common slip when expanding $\\log \\dfrac{a}{c^{2} d}$?', r`Forgetting that the minus applies to both factors: $\log a - 2\log c - \log d$, not $\log a - 2\log c + \log d$.`, 'exam-tip', 3),
    fc('f28', 'Common slip with $\\dfrac{\\log m}{\\log n}$?', r`It is **not** $\log m - \log n$. The quotient law needs $\log \dfrac{m}{n}$.`, 'exam-tip', 2),
    fc('f29', 'Picture: the curve $y = \\log x$. Where does it cross the $x$-axis, and where does it exist?', r`It crosses at $x = 1$ (since $\log 1 = 0$) and exists only for $x > 0$.`, 'diagram', 1),
    fc('f30', 'Picture: flow chart for the product law. What are its steps?', r`$\log_{a} m = x$, $\log_{a} n = y$; $m = a^{x}$, $n = a^{y}$; $mn = a^{x+y}$; so $\log_{a}(mn) = x + y$.`, 'diagram', 2),
  ],
  status: 'draft', provenance: d1.provenance,
};

